-- -----------------------------------------------------------------------------
-- Account deletion log. Deliberately contains NO personal data: only a SHA-256
-- hash of the user id, timestamps, outcome and the status of external cleanup.
-- It survives the deletion so operators can prove a deletion was carried out.
-- Service role only (no policies, no grants to users).
-- -----------------------------------------------------------------------------
create table public.account_deletion_log (
  id uuid primary key default gen_random_uuid(),
  subject_hash text not null check (subject_hash ~ '^[a-f0-9]{64}$'),
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  outcome text not null default 'started' check (outcome in ('started', 'completed', 'failed')),
  -- e.g. {"walrus": "not_applicable"} — external stores report their own status.
  external_cleanup jsonb not null default '{}'::jsonb check (jsonb_typeof(external_cleanup) = 'object')
);

alter table public.account_deletion_log enable row level security;
revoke all on table public.account_deletion_log from anon, authenticated;

-- >>> 20261031000400_new_user_bootstrap.sql
-- =============================================================================
-- AVEN Stage 1 — Migration 4: New-user bootstrap
-- When Supabase Auth creates a user, create their profile and default settings.
-- No financial, wellbeing or sample data is created — new users start empty.
-- =============================================================================

create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := nullif(btrim(coalesce(new.raw_user_meta_data ->> 'display_name', '')), '');
begin
  -- Never let a bad display name block sign-up; store nothing instead.
  if v_name is not null and char_length(v_name) > 80 then
    v_name := null;
  end if;

  insert into public.profiles (id, display_name) values (new.id, v_name);
  insert into public.user_preferences (user_id) values (new.id);
  insert into public.notification_preferences (user_id) values (new.id);
  insert into public.ai_usage_limits (user_id) values (new.id);

  insert into public.notification_category_preferences (user_id, category, frequency) values
    (new.id, 'subscriptions',    'daily_digest'),
    (new.id, 'shared_expenses',  'daily_digest'),
    (new.id, 'budgets',          'daily_digest'),
    (new.id, 'savings',          'weekly_digest'),
    (new.id, 'routines',         'daily_digest'),
    (new.id, 'wellbeing',        'weekly_digest'),
    (new.id, 'planning',         'daily_digest'),
    (new.id, 'account_security', 'immediate');

  -- Every consent category starts explicitly NOT granted.
  insert into public.consent_state (user_id, category, granted, policy_version)
  select new.id, c.category, false, c.policy_version from public.consent_categories c;

  perform private.write_audit(new.id, 'account.created', '{}'::jsonb);
  return new;
end;
$$;

revoke all on function private.handle_new_user() from public;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

-- -----------------------------------------------------------------------------
-- Account deletion clean-up for data that is not linked by a foreign key.
-- (Rate-limit buckets are keyed by text so they can be pruned cheaply.)
-- -----------------------------------------------------------------------------
create or replace function private.cleanup_deleted_profile()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.rate_limit_buckets where bucket_key like old.id::text || ':%';
  return old;
end;
$$;

revoke all on function private.cleanup_deleted_profile() from public;

create trigger on_profile_deleted
  after delete on public.profiles
  for each row execute function private.cleanup_deleted_profile();

-- >>> 20261101000100_finance_tables.sql
-- =============================================================================
-- AVEN Stage 2 — Migration 5: Finance tables
--
-- Design rules (see docs/DATABASE.md → "Finance"):
--   * Money is bigint MINOR units + a currency code. Per-row amounts are capped
--     at 9,000,000,000,000,000 so they stay exact in JavaScript.
--   * Balances are NEVER stored. They are calculated from the opening balance
--     plus transactions, so they cannot drift or be double-counted.
--   * A transfer is ONE row naming both accounts, so it is atomic by design.
--   * Users may only READ these tables. Every write goes through
--     public.apply_finance_mutation() (next migration), which validates
--     ownership, enforces versions and records idempotency receipts.
--   * Triggers below re-check cross-table ownership and currency rules on
--     every write, whatever the write path (defence in depth).
-- =============================================================================

-- Shared limit for a single stored amount (fits in JS Number.MAX_SAFE_INTEGER).
create or replace function private.max_amount_minor()
returns bigint
language sql
immutable
set search_path = ''
as $$ select 9000000000000000::bigint $$;

-- Keep a monotonically increasing row version for conflict detection.
create or replace function private.bump_version()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.version := old.version + 1;
  new.updated_at := now();
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Financial accounts
-- -----------------------------------------------------------------------------
create table public.financial_accounts (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  account_type text not null check (
    account_type in ('cash', 'bank', 'savings', 'credit_card', 'digital_wallet', 'other')
  ),
  currency_code text not null references public.currencies (code),
  -- May be negative (e.g. an existing credit-card balance).
  opening_balance_minor bigint not null default 0
    check (abs(opening_balance_minor) <= private.max_amount_minor()),
  description text check (description is null or char_length(description) <= 500),
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index financial_accounts_user_idx on public.financial_accounts (user_id);
create unique index financial_accounts_active_name_uniq
  on public.financial_accounts (user_id, lower(btrim(name)))
  where archived_at is null;

-- Currency cannot change once set: existing transactions were recorded in it.
create or replace function private.guard_account_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.currency_code <> old.currency_code then
    raise exception 'An account''s currency cannot be changed' using errcode = '22023';
  end if;
  if new.user_id <> old.user_id then
    raise exception 'Ownership cannot change' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger financial_accounts_guard
  before update on public.financial_accounts
  for each row execute function private.guard_account_update();
create trigger financial_accounts_version
  before update on public.financial_accounts
  for each row execute function private.bump_version();

alter table public.financial_accounts enable row level security;
revoke all on table public.financial_accounts from anon, authenticated;
grant select on table public.financial_accounts to authenticated;
create policy "Users can read their own financial accounts"
  on public.financial_accounts for select to authenticated
  using (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Transaction categories (per-user; defaults are seeded per user and editable)
-- -----------------------------------------------------------------------------
create table public.transaction_categories (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('income', 'expense')),
  name text not null check (char_length(btrim(name)) between 1 and 50),
  is_default boolean not null default false,
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index transaction_categories_user_idx on public.transaction_categories (user_id, kind);
create unique index transaction_categories_active_name_uniq
  on public.transaction_categories (user_id, kind, lower(btrim(name)))
  where archived_at is null;

create or replace function private.guard_category_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.kind <> old.kind then
    raise exception 'A category''s type cannot be changed' using errcode = '22023';
  end if;
  if new.user_id <> old.user_id then
    raise exception 'Ownership cannot change' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger transaction_categories_guard
  before update on public.transaction_categories
  for each row execute function private.guard_category_update();
create trigger transaction_categories_version
  before update on public.transaction_categories
  for each row execute function private.bump_version();

alter table public.transaction_categories enable row level security;
revoke all on table public.transaction_categories from anon, authenticated;
grant select on table public.transaction_categories to authenticated;
create policy "Users can read their own categories"
  on public.transaction_categories for select to authenticated
  using (user_id = (select auth.uid()));

-- Default categories, created for every user.
create or replace function private.seed_default_categories(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.transaction_categories (id, user_id, kind, name, is_default)
  select gen_random_uuid(), p_user_id, d.kind, d.name, true
  from (values
    ('income', 'Salary'), ('income', 'Freelance'), ('income', 'Business'),
    ('income', 'Investments'), ('income', 'Gifts'), ('income', 'Other income'),
    ('expense', 'Food'), ('expense', 'Transport'), ('expense', 'Housing'),
    ('expense', 'Bills'), ('expense', 'Shopping'), ('expense', 'Health'),
    ('expense', 'Education'), ('expense', 'Entertainment'), ('expense', 'Subscriptions'),
    ('expense', 'Travel'), ('expense', 'Personal care'), ('expense', 'Other expenses')
  ) as d(kind, name)
  where not exists (
    select 1 from public.transaction_categories c
    where c.user_id = p_user_id and c.kind = d.kind and lower(c.name) = lower(d.name)
      and c.archived_at is null
  );
end;
$$;
revoke all on function private.seed_default_categories(uuid) from public;

create or replace function private.on_profile_created_seed_categories()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.seed_default_categories(new.id);
  return new;
end;
$$;
revoke all on function private.on_profile_created_seed_categories() from public;

create trigger on_profile_created_seed_categories
  after insert on public.profiles
  for each row execute function private.on_profile_created_seed_categories();

-- Existing Stage 1 users get the defaults too (safe to re-run; skips duplicates).
do $$
declare
  v_id uuid;
begin
  for v_id in select id from public.profiles loop
    perform private.seed_default_categories(v_id);
  end loop;
end
$$;

-- -----------------------------------------------------------------------------
-- Transactions
--   kind = income   : +amount to account_id
--   kind = expense  : -amount from account_id
--   kind = transfer : -amount from account_id, +amount to transfer_account_id
-- -----------------------------------------------------------------------------
create table public.transactions (
  id uuid primary key,  -- generated on the device, stable across offline sync
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('income', 'expense', 'transfer')),
  account_id uuid not null references public.financial_accounts (id) on delete cascade,
  transfer_account_id uuid references public.financial_accounts (id) on delete cascade,
  amount_minor bigint not null check (amount_minor > 0 and amount_minor <= private.max_amount_minor()),
  currency_code text not null references public.currencies (code),
  category_id uuid references public.transaction_categories (id) on delete set null,
  description text check (description is null or char_length(description) <= 200),
  merchant text check (merchant is null or char_length(merchant) <= 120),
  notes text check (notes is null or char_length(notes) <= 1000),
  occurred_on date not null check (occurred_on between date '1970-01-01' and date '2200-12-31'),
  -- Reserved for receipt uploads in a later stage (Supabase Storage path).
  attachment_ref text check (attachment_ref is null or char_length(attachment_ref) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (kind = 'transfer' and transfer_account_id is not null and transfer_account_id <> account_id and category_id is null)
    or (kind <> 'transfer' and transfer_account_id is null)
  )
);

create index transactions_user_date_idx on public.transactions (user_id, occurred_on desc, created_at desc);
create index transactions_account_idx on public.transactions (account_id);
create index transactions_transfer_account_idx on public.transactions (transfer_account_id) where transfer_account_id is not null;
create index transactions_category_idx on public.transactions (category_id) where category_id is not null;

-- Cross-table integrity, enforced on EVERY write path.
create or replace function private.guard_transaction()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_account public.financial_accounts%rowtype;
  v_target public.financial_accounts%rowtype;
  v_category public.transaction_categories%rowtype;
begin
  if tg_op = 'UPDATE' and new.user_id <> old.user_id then
    raise exception 'Ownership cannot change' using errcode = '42501';
  end if;

  select * into v_account from public.financial_accounts where id = new.account_id;
  if not found or v_account.user_id <> new.user_id then
    raise exception 'Account not found' using errcode = '42501';
  end if;
  if new.currency_code <> v_account.currency_code then
    raise exception 'Transaction currency must match the account currency' using errcode = '22023';
  end if;

  if new.kind = 'transfer' then
    select * into v_target from public.financial_accounts where id = new.transfer_account_id;
    if not found or v_target.user_id <> new.user_id then
      raise exception 'Destination account not found' using errcode = '42501';
    end if;
    if v_target.currency_code <> v_account.currency_code then
      raise exception 'Transfers are only allowed between accounts in the same currency'
        using errcode = '22023';
    end if;
  end if;

  if new.category_id is not null then
    select * into v_category from public.transaction_categories where id = new.category_id;
    if not found or v_category.user_id <> new.user_id then
      raise exception 'Category not found' using errcode = '42501';
    end if;
    if v_category.kind <> new.kind then
      raise exception 'Category type does not match the transaction type' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

create trigger transactions_guard
  before insert or update on public.transactions
  for each row execute function private.guard_transaction();
create trigger transactions_version
  before update on public.transactions
  for each row execute function private.bump_version();

alter table public.transactions enable row level security;
revoke all on table public.transactions from anon, authenticated;
grant select on table public.transactions to authenticated;
create policy "Users can read their own transactions"
  on public.transactions for select to authenticated
  using (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Budgets (monthly). category_id NULL = all expenses in that currency.
-- Spending is calculated from expense transactions only.
-- -----------------------------------------------------------------------------
create table public.budgets (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  category_id uuid references public.transaction_categories (id) on delete cascade,
  currency_code text not null references public.currencies (code),
  limit_minor bigint not null check (limit_minor > 0 and limit_minor <= private.max_amount_minor()),
  alert_threshold_pct smallint not null default 80 check (alert_threshold_pct between 1 and 100),
  starts_on date not null check (extract(day from starts_on) = 1),
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index budgets_user_idx on public.budgets (user_id);
create unique index budgets_active_scope_uniq
  on public.budgets (user_id, currency_code, coalesce(category_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where archived_at is null;

create or replace function private.guard_budget()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_category public.transaction_categories%rowtype;
begin
  if tg_op = 'UPDATE' and (new.user_id <> old.user_id or new.currency_code <> old.currency_code) then
    raise exception 'A budget''s owner and currency cannot change' using errcode = '22023';
  end if;
  if new.category_id is not null then
    select * into v_category from public.transaction_categories where id = new.category_id;
    if not found or v_category.user_id <> new.user_id then
      raise exception 'Category not found' using errcode = '42501';
    end if;
    if v_category.kind <> 'expense' then
      raise exception 'Budgets can only track expense categories' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

create trigger budgets_guard
  before insert or update on public.budgets
  for each row execute function private.guard_budget();
create trigger budgets_version
  before update on public.budgets
  for each row execute function private.bump_version();

alter table public.budgets enable row level security;
revoke all on table public.budgets from anon, authenticated;
grant select on table public.budgets to authenticated;
create policy "Users can read their own budgets"
  on public.budgets for select to authenticated
  using (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Savings goals and their entries.
-- Entries are TRACKING RECORDS. They never change any account balance.
-- -----------------------------------------------------------------------------
create table public.savings_goals (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  currency_code text not null references public.currencies (code),
  target_minor bigint not null check (target_minor > 0 and target_minor <= private.max_amount_minor()),
  target_date date,
  description text check (description is null or char_length(description) <= 500),
  status text not null default 'active' check (status in ('active', 'paused', 'completed', 'archived')),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index savings_goals_user_idx on public.savings_goals (user_id);

create or replace function private.guard_goal_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.user_id <> old.user_id or new.currency_code <> old.currency_code then
    raise exception 'A goal''s owner and currency cannot change' using errcode = '22023';
  end if;
  return new;
end;
$$;

create trigger savings_goals_guard
  before update on public.savings_goals
  for each row execute function private.guard_goal_update();
create trigger savings_goals_version
  before update on public.savings_goals
  for each row execute function private.bump_version();

alter table public.savings_goals enable row level security;
revoke all on table public.savings_goals from anon, authenticated;
grant select on table public.savings_goals to authenticated;
create policy "Users can read their own savings goals"
  on public.savings_goals for select to authenticated
  using (user_id = (select auth.uid()));

create table public.savings_goal_entries (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  goal_id uuid not null references public.savings_goals (id) on delete cascade,
  kind text not null check (kind in ('contribution', 'withdrawal')),
  amount_minor bigint not null check (amount_minor > 0 and amount_minor <= private.max_amount_minor()),
  occurred_on date not null,
  note text check (note is null or char_length(note) <= 200),
  created_at timestamptz not null default now()
);

create index savings_goal_entries_goal_idx on public.savings_goal_entries (goal_id, occurred_on desc);

-- Ownership + "a withdrawal can't exceed what has been saved", race-free:
-- the goal row is locked so two concurrent withdrawals cannot both pass.
create or replace function private.guard_goal_entry()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_goal public.savings_goals%rowtype;
  v_saved bigint;
begin
  select * into v_goal from public.savings_goals where id = new.goal_id for update;
  if not found or v_goal.user_id <> new.user_id then
    raise exception 'Goal not found' using errcode = '42501';
  end if;
  if new.kind = 'withdrawal' then
    select coalesce(sum(case when e.kind = 'contribution' then e.amount_minor else -e.amount_minor end), 0)
      into v_saved
    from public.savings_goal_entries e where e.goal_id = new.goal_id;
    if new.amount_minor > v_saved then
      raise exception 'A withdrawal cannot be larger than the amount saved' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

create trigger savings_goal_entries_guard
  before insert on public.savings_goal_entries
  for each row execute function private.guard_goal_entry();

alter table public.savings_goal_entries enable row level security;
revoke all on table public.savings_goal_entries from anon, authenticated;
grant select on table public.savings_goal_entries to authenticated;
create policy "Users can read their own goal entries"
  on public.savings_goal_entries for select to authenticated
  using (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Finance events: deterministic facts for the future Nudge Center (Stage 3).
-- They are NOT notifications. dedupe_key prevents repeats (no spam).
-- -----------------------------------------------------------------------------
create table public.finance_events (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in (
    'budget_threshold_reached', 'budget_exceeded', 'savings_milestone_reached',
    'sync_failed', 'sync_completed'
  )),
  dedupe_key text not null check (char_length(dedupe_key) <= 200),
  payload jsonb not null default '{}'::jsonb check (jsonb_typeof(payload) = 'object' and pg_column_size(payload) <= 2048),
  occurred_at timestamptz not null default now(),
  processed_at timestamptz,
  unique (user_id, dedupe_key)
);

create index finance_events_unprocessed_idx on public.finance_events (user_id, occurred_at) where processed_at is null;

alter table public.finance_events enable row level security;
revoke all on table public.finance_events from anon, authenticated;
grant select on table public.finance_events to authenticated;
create policy "Users can read their own finance events"
  on public.finance_events for select to authenticated
  using (user_id = (select auth.uid()));

create or replace function private.record_finance_event(p_user uuid, p_kind text, p_key text, p_payload jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.finance_events (user_id, kind, dedupe_key, payload)
  values (p_user, p_kind, p_key, coalesce(p_payload, '{}'::jsonb))
  on conflict (user_id, dedupe_key) do nothing;
end;
$$;
revoke all on function private.record_finance_event(uuid, text, text, jsonb) from public;

-- -----------------------------------------------------------------------------
-- Sync receipts: from Stage 2 they are written ONLY by apply_finance_mutation().
-- Store the exact response so a retried mutation gets the identical answer.
-- -----------------------------------------------------------------------------
alter table public.sync_receipts add column response jsonb;
revoke insert on table public.sync_receipts from authenticated;
drop policy "Users can record their own sync receipts" on public.sync_receipts;

-- >>> 20261101000200_finance_mutations.sql
-- =============================================================================
-- AVEN Stage 2 — Migration 6: The finance write path
--
-- public.apply_finance_mutation() is the ONLY way to change finance data.
-- For every call it:
--   1. identifies the user from the session (auth.uid()), never from input;
--   2. serialises calls with the same mutation id and replays the stored
--      response if that mutation was already processed (idempotency);
--   3. checks ownership of every referenced record explicitly;
--   4. enforces optimistic concurrency (base_version must match);
--   5. turns rule violations into a clean "rejected" result (no data leaks);
--   6. stores a receipt with the exact response, all in ONE transaction.
-- =============================================================================

create or replace function private.result(p_status text, p_extra jsonb default '{}'::jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$ select jsonb_build_object('status', p_status) || coalesce(p_extra, '{}'::jsonb) $$;

create or replace function private.jtext(p jsonb, k text)
returns text
language sql
immutable
set search_path = ''
as $$ select nullif(btrim(p ->> k), '') $$;

-- -----------------------------------------------------------------------------
-- Finance event producers (deterministic; dedupe keys prevent repeats)
-- -----------------------------------------------------------------------------
create or replace function private.check_budget_events(
  p_user uuid, p_currency text, p_category uuid, p_on date
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_month date := date_trunc('month', p_on)::date;
  v_budget public.budgets%rowtype;
  v_spent bigint;
  v_key text;
begin
  for v_budget in
    select * from public.budgets b
    where b.user_id = p_user and b.archived_at is null and b.currency_code = p_currency
      and b.starts_on <= v_month
      and (b.category_id is null or b.category_id = p_category)
  loop
    select coalesce(sum(t.amount_minor), 0) into v_spent
    from public.transactions t
    where t.user_id = p_user and t.kind = 'expense' and t.currency_code = p_currency
      and t.occurred_on >= v_month and t.occurred_on < (v_month + interval '1 month')
      and (v_budget.category_id is null or t.category_id = v_budget.category_id);

    v_key := 'budget:' || v_budget.id || ':' || to_char(v_month, 'YYYY-MM');
    if v_spent > v_budget.limit_minor then
      perform private.record_finance_event(p_user, 'budget_exceeded', v_key || ':exceeded',
        jsonb_build_object('budget_id', v_budget.id, 'month', v_month,
          'spent_minor', v_spent::text, 'limit_minor', v_budget.limit_minor::text, 'currency_code', p_currency));
    elsif v_spent * 100 >= v_budget.limit_minor * v_budget.alert_threshold_pct then
      perform private.record_finance_event(p_user, 'budget_threshold_reached', v_key || ':threshold',
        jsonb_build_object('budget_id', v_budget.id, 'month', v_month, 'threshold_pct', v_budget.alert_threshold_pct,
          'spent_minor', v_spent::text, 'limit_minor', v_budget.limit_minor::text, 'currency_code', p_currency));
    end if;
  end loop;
end;
$$;
revoke all on function private.check_budget_events(uuid, text, uuid, date) from public;

create or replace function private.check_goal_milestones(p_user uuid, p_goal uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_goal public.savings_goals%rowtype;
  v_saved bigint;
  v_pct integer;
begin
  select * into v_goal from public.savings_goals where id = p_goal and user_id = p_user;
  if not found then return; end if;
  select coalesce(sum(case when kind = 'contribution' then amount_minor else -amount_minor end), 0)
    into v_saved from public.savings_goal_entries where goal_id = p_goal;
  foreach v_pct in array array[25, 50, 75, 100] loop
    if v_saved * 100 >= v_goal.target_minor * v_pct then
      perform private.record_finance_event(p_user, 'savings_milestone_reached',
        'goal:' || p_goal || ':milestone:' || v_pct,
        jsonb_build_object('goal_id', p_goal, 'milestone_pct', v_pct, 'saved_minor', v_saved::text,
          'target_minor', v_goal.target_minor::text, 'currency_code', v_goal.currency_code));
    end if;
  end loop;
end;
$$;
revoke all on function private.check_goal_milestones(uuid, uuid) from public;

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------
create or replace function private.require_active_account(p_user uuid, p_account uuid, p_allow_archived uuid default null)
returns public.financial_accounts
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.financial_accounts%rowtype;
begin
  select * into v from public.financial_accounts where id = p_account and user_id = p_user;
  if not found then
    raise exception 'Account not found' using errcode = '42501';
  end if;
  if v.archived_at is not null and p_account is distinct from p_allow_archived then
    raise exception 'This account is archived. Restore it before adding transactions.' using errcode = 'P0001';
  end if;
  return v;
end;
$$;
revoke all on function private.require_active_account(uuid, uuid, uuid) from public;

-- -----------------------------------------------------------------------------
-- Entity handlers
-- -----------------------------------------------------------------------------
create or replace function private.fin_transaction(
  p_user uuid, p_op text, p_id uuid, p jsonb, p_base bigint
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.transactions%rowtype;
  v_account public.financial_accounts%rowtype;
  v_kind text := private.jtext(p, 'kind');
  v_transfer uuid := private.jtext(p, 'transfer_account_id')::uuid;
begin
  if p_op in ('update', 'delete') then
    select * into v_row from public.transactions where id = p_id and user_id = p_user for update;
    if not found then
      if p_op = 'delete' then
        return private.result('applied', jsonb_build_object('note', 'already_deleted'));
      end if;
      return private.result('conflict', jsonb_build_object('reason', 'not_found',
        'message', 'This transaction no longer exists on the server.'));
    end if;
    if p_base is null or p_base <> v_row.version then
      return private.result('conflict', jsonb_build_object('reason', 'version',
        'message', 'This transaction was changed somewhere else.',
        'server_version', v_row.version, 'record', to_jsonb(v_row)));
    end if;
    if p_op = 'delete' then
      delete from public.transactions where id = p_id;
      return private.result('applied', jsonb_build_object('server_version', v_row.version));
    end if;
  else
    if exists (select 1 from public.transactions where id = p_id) then
      select * into v_row from public.transactions where id = p_id and user_id = p_user;
      if found then
        return private.result('conflict', jsonb_build_object('reason', 'exists',
          'message', 'A transaction with this id already exists.',
          'server_version', v_row.version, 'record', to_jsonb(v_row)));
      end if;
      raise exception 'Not found' using errcode = '42501';
    end if;
  end if;

  -- Accounts must belong to the user; archived accounts only allowed if unchanged.
  v_account := private.require_active_account(p_user, private.jtext(p, 'account_id')::uuid,
    case when p_op = 'update' then v_row.account_id end);
  if v_kind = 'transfer' then
    perform private.require_active_account(p_user, v_transfer,
      case when p_op = 'update' then v_row.transfer_account_id end);
  end if;
  -- The amount was entered with this currency's precision; it must match the account.
  if private.jtext(p, 'currency_code') is distinct from v_account.currency_code then
    raise exception 'Currency does not match the account' using errcode = '22023';
  end if;

  if p_op = 'create' then
    insert into public.transactions (
      id, user_id, kind, account_id, transfer_account_id, amount_minor, currency_code,
      category_id, description, merchant, notes, occurred_on
    ) values (
      p_id, p_user, v_kind, v_account.id, v_transfer, (p ->> 'amount_minor')::bigint, v_account.currency_code,
      private.jtext(p, 'category_id')::uuid, private.jtext(p, 'description'), private.jtext(p, 'merchant'),
      private.jtext(p, 'notes'), (p ->> 'occurred_on')::date
    ) returning * into v_row;
  else
    update public.transactions set
      kind = v_kind,
      account_id = v_account.id,
      transfer_account_id = v_transfer,
      amount_minor = (p ->> 'amount_minor')::bigint,
      currency_code = v_account.currency_code,
      category_id = private.jtext(p, 'category_id')::uuid,
      description = private.jtext(p, 'description'),
      merchant = private.jtext(p, 'merchant'),
      notes = private.jtext(p, 'notes'),
      occurred_on = (p ->> 'occurred_on')::date
    where id = p_id
    returning * into v_row;
  end if;

  if v_row.kind = 'expense' then
    perform private.check_budget_events(p_user, v_row.currency_code, v_row.category_id, v_row.occurred_on);
  end if;
  return private.result('applied', jsonb_build_object('server_version', v_row.version, 'record', to_jsonb(v_row)));
end;
$$;
revoke all on function private.fin_transaction(uuid, text, uuid, jsonb, bigint) from public;

create or replace function private.fin_account(p_user uuid, p_op text, p_id uuid, p jsonb, p_base bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.financial_accounts%rowtype;
begin
  if p_op = 'create' then
    if exists (select 1 from public.financial_accounts where id = p_id) then
      raise exception 'Not found' using errcode = '42501';
    end if;
    insert into public.financial_accounts (id, user_id, name, account_type, currency_code, opening_balance_minor, description)
    values (p_id, p_user, btrim(p ->> 'name'), p ->> 'account_type', p ->> 'currency_code',
      coalesce((p ->> 'opening_balance_minor')::bigint, 0), private.jtext(p, 'description'))
    returning * into v_row;
  else
    select * into v_row from public.financial_accounts where id = p_id and user_id = p_user for update;
    if not found then
      return private.result('conflict', jsonb_build_object('reason', 'not_found', 'message', 'Account not found.'));
    end if;
    if p_base is null or p_base <> v_row.version then
      return private.result('conflict', jsonb_build_object('reason', 'version',
        'message', 'This account was changed somewhere else.', 'server_version', v_row.version, 'record', to_jsonb(v_row)));
    end if;
    update public.financial_accounts set
      name = coalesce(btrim(p ->> 'name'), name),
      account_type = coalesce(p ->> 'account_type', account_type),
      opening_balance_minor = coalesce((p ->> 'opening_balance_minor')::bigint, opening_balance_minor),
      description = case when p ? 'description' then private.jtext(p, 'description') else description end,
      archived_at = case
        when (p ->> 'archived')::boolean is true then coalesce(archived_at, now())
        when (p ->> 'archived')::boolean is false then null
        else archived_at end
    where id = p_id returning * into v_row;
  end if;
  return private.result('applied', jsonb_build_object('server_version', v_row.version, 'record', to_jsonb(v_row)));
end;
$$;
revoke all on function private.fin_account(uuid, text, uuid, jsonb, bigint) from public;

