create or replace function private.fin_goal_entry(p_user uuid, p_op text, p_id uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.savings_goal_entries%rowtype;
  v_goal public.savings_goals%rowtype;
  v_saved bigint;
begin
  if p_op = 'delete' then
    select * into v_row from public.savings_goal_entries where id = p_id and user_id = p_user for update;
    if not found then
      return private.result('applied', jsonb_build_object('note', 'already_deleted'));
    end if;
    -- Removing a contribution must not leave the goal with a negative saved amount.
    if v_row.kind = 'contribution' then
      perform 1 from public.savings_goals where id = v_row.goal_id for update;
      select coalesce(sum(case when kind = 'contribution' then amount_minor else -amount_minor end), 0)
        into v_saved from public.savings_goal_entries where goal_id = v_row.goal_id;
      if v_saved - v_row.amount_minor < 0 then
        raise exception 'Remove the later withdrawals first: this would make the saved amount negative.'
          using errcode = 'P0001';
      end if;
    end if;
    delete from public.savings_goal_entries where id = p_id;
    return private.result('applied');
  end if;

  if exists (select 1 from public.savings_goal_entries where id = p_id) then
    raise exception 'Not found' using errcode = '42501';
  end if;
  select * into v_goal from public.savings_goals where id = (p ->> 'goal_id')::uuid and user_id = p_user;
  if not found then
    raise exception 'Goal not found' using errcode = '42501';
  end if;
  if v_goal.status = 'archived' then
    raise exception 'This goal is archived.' using errcode = 'P0001';
  end if;
  insert into public.savings_goal_entries (id, user_id, goal_id, kind, amount_minor, occurred_on, note)
  values (p_id, p_user, v_goal.id, p ->> 'kind', (p ->> 'amount_minor')::bigint,
    (p ->> 'occurred_on')::date, private.jtext(p, 'note'))
  returning * into v_row;
  if v_row.kind = 'contribution' then
    perform private.check_goal_milestones(p_user, v_goal.id);
  end if;
  return private.result('applied', jsonb_build_object('record', to_jsonb(v_row)));
end;
$$;
revoke all on function private.fin_goal_entry(uuid, text, uuid, jsonb) from public;

-- -----------------------------------------------------------------------------
-- The public entry point
-- -----------------------------------------------------------------------------
create or replace function public.apply_finance_mutation(
  p_mutation_id uuid,
  p_entity text,
  p_operation text,
  p_record_id uuid,
  p_payload jsonb,
  p_base_version bigint default null,
  p_device_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_existing jsonb;
  v_result jsonb;
  v_device uuid;
  v_message text;
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_mutation_id is null or p_record_id is null then
    raise exception 'Mutation and record ids are required' using errcode = '22023';
  end if;
  if not (
    (p_entity = 'transaction' and p_operation in ('create', 'update', 'delete'))
    or (p_entity in ('financial_account', 'category', 'budget', 'savings_goal') and p_operation in ('create', 'update'))
    or (p_entity = 'savings_goal_entry' and p_operation in ('create', 'delete'))
  ) then
    raise exception 'Unsupported mutation: % %', p_entity, p_operation using errcode = '22023';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' or pg_column_size(p_payload) > 8192 then
    raise exception 'Invalid payload' using errcode = '22023';
  end if;

  -- Serialise concurrent deliveries of the same mutation, then replay if already done.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text || ':' || p_mutation_id::text, 0));
  select r.response into v_existing
  from public.sync_receipts r
  where r.user_id = v_user and r.client_mutation_id = p_mutation_id;
  if found then
    return coalesce(v_existing, private.result('applied')) || jsonb_build_object('replayed', true);
  end if;

  -- Register the device (ignored if the id belongs to someone else).
  if p_device_id is not null then
    insert into public.user_devices (id, user_id) values (p_device_id, v_user)
    on conflict (id) do update set last_seen_at = now(), last_sync_at = now()
      where public.user_devices.user_id = v_user;
    select id into v_device from public.user_devices where id = p_device_id and user_id = v_user;
  end if;

  begin
    v_result := case p_entity
      when 'transaction' then private.fin_transaction(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'financial_account' then private.fin_account(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'category' then private.fin_category(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'budget' then private.fin_budget(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'savings_goal' then private.fin_goal(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'savings_goal_entry' then private.fin_goal_entry(v_user, p_operation, p_record_id, p_payload)
    end;
  exception
    when insufficient_privilege then
      -- Never reveal whether a record exists for another user.
      v_result := private.result('rejected', jsonb_build_object('message', 'Not found.'));
    when unique_violation then
      v_result := private.result('rejected', jsonb_build_object('message', 'Something with that name already exists.'));
    when check_violation or not_null_violation or foreign_key_violation then
      v_result := private.result('rejected', jsonb_build_object('message', 'Some of the details are not valid.'));
    when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format
      or datetime_field_overflow or invalid_parameter_value or raise_exception then
      get stacked diagnostics v_message = message_text;
      v_result := private.result('rejected', jsonb_build_object('message', left(v_message, 200)));
  end;

  insert into public.sync_receipts (
    user_id, client_mutation_id, device_id, entity, record_id, operation, result, server_version, response
  ) values (
    v_user, p_mutation_id, v_device, p_entity, p_record_id, p_operation,
    v_result ->> 'status', (v_result ->> 'server_version')::bigint, v_result
  );

  if p_entity = 'transaction' and v_result ->> 'status' <> 'applied' then
    perform private.record_finance_event(v_user, 'sync_failed', 'sync_failed:' || p_mutation_id,
      jsonb_build_object('mutation_id', p_mutation_id, 'record_id', p_record_id,
        'status', v_result ->> 'status', 'reason', v_result ->> 'reason'));
  end if;
  return v_result;
end;
$$;
revoke all on function public.apply_finance_mutation(uuid, text, text, uuid, jsonb, bigint, uuid) from public, anon;
grant execute on function public.apply_finance_mutation(uuid, text, text, uuid, jsonb, bigint, uuid) to authenticated;

-- One "sync completed" fact per offline sync batch (dedupe by batch id).
create or replace function public.record_sync_completed(p_batch_id uuid, p_applied integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_applied is null or p_applied < 1 or p_applied > 1000 then
    raise exception 'Invalid count' using errcode = '22023';
  end if;
  perform private.record_finance_event(v_user, 'sync_completed', 'sync_completed:' || p_batch_id,
    jsonb_build_object('applied', p_applied));
end;
$$;
revoke all on function public.record_sync_completed(uuid, integer) from public, anon;
grant execute on function public.record_sync_completed(uuid, integer) to authenticated;

-- >>> 20261101000300_finance_reads.sql
-- =============================================================================
-- AVEN Stage 2 — Migration 7: Finance read models
--
-- Every view/function here is SECURITY INVOKER: it runs as the signed-in user,
-- so Row Level Security limits results to that user's own rows.
-- Aggregated money is returned as TEXT so large sums stay exact in JavaScript.
-- Transfers are NEVER counted as income or expenses.
-- =============================================================================

-- Balance = opening balance + income − expenses − transfers out + transfers in.
create view public.account_balances
with (security_invoker = true)
as
select
  a.id as account_id,
  a.user_id,
  a.currency_code,
  (a.opening_balance_minor + coalesce(sum(
    case
      when t.kind = 'income' then t.amount_minor
      when t.kind = 'expense' then -t.amount_minor
      when t.kind = 'transfer' and t.account_id = a.id then -t.amount_minor
      when t.kind = 'transfer' and t.transfer_account_id = a.id then t.amount_minor
      else 0
    end), 0))::text as balance_minor,
  count(t.id)::integer as transaction_count,
  max(t.occurred_on) as last_activity_on
from public.financial_accounts a
left join public.transactions t
  on t.user_id = a.user_id and (t.account_id = a.id or t.transfer_account_id = a.id)
group by a.id;

revoke all on public.account_balances from anon, authenticated;
grant select on public.account_balances to authenticated;

create view public.savings_goal_progress
with (security_invoker = true)
as
select
  g.id as goal_id,
  g.user_id,
  coalesce(sum(case when e.kind = 'contribution' then e.amount_minor else -e.amount_minor end), 0)::text as saved_minor,
  count(e.id)::integer as entry_count
from public.savings_goals g
left join public.savings_goal_entries e on e.goal_id = g.id
group by g.id;

revoke all on public.savings_goal_progress from anon, authenticated;
grant select on public.savings_goal_progress to authenticated;

-- Income / expense / net per currency for a date range (inclusive).
create or replace function public.finance_summary(p_from date, p_to date)
returns table (
  currency_code text,
  income_minor text,
  expense_minor text,
  net_minor text,
  transaction_count integer
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    t.currency_code,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'income'), 0)::text,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'expense'), 0)::text,
    (coalesce(sum(t.amount_minor) filter (where t.kind = 'income'), 0)
      - coalesce(sum(t.amount_minor) filter (where t.kind = 'expense'), 0))::text,
    count(*)::integer
  from public.transactions t
  where t.kind in ('income', 'expense') and t.occurred_on between p_from and p_to
  group by t.currency_code
  order by t.currency_code;
$$;

create or replace function public.spending_by_category(p_from date, p_to date)
returns table (
  currency_code text,
  category_id uuid,
  category_name text,
  expense_minor text
)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.currency_code, t.category_id, coalesce(c.name, 'Uncategorised'), sum(t.amount_minor)::text
  from public.transactions t
  left join public.transaction_categories c on c.id = t.category_id
  where t.kind = 'expense' and t.occurred_on between p_from and p_to
  group by t.currency_code, t.category_id, c.name
  order by t.currency_code, sum(t.amount_minor) desc;
$$;

-- Month-by-month income and expenses for the last p_months months ending at p_today's month.
create or replace function public.monthly_cashflow(p_months integer, p_today date)
returns table (
  month date,
  currency_code text,
  income_minor text,
  expense_minor text
)
language sql
stable
security invoker
set search_path = ''
as $$
  with bounds as (
    select date_trunc('month', p_today)::date as last_month,
           (date_trunc('month', p_today) - make_interval(months => greatest(1, least(p_months, 24)) - 1))::date as first_month
  ),
  currencies as (
    select distinct t.currency_code from public.transactions t, bounds b
    where t.kind in ('income', 'expense') and t.occurred_on >= b.first_month
  ),
  months as (
    select generate_series(b.first_month, b.last_month, interval '1 month')::date as month from bounds b
  )
  select m.month, c.currency_code,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'income'), 0)::text,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'expense'), 0)::text
  from months m
  cross join currencies c
  left join public.transactions t
    on t.currency_code = c.currency_code and t.kind in ('income', 'expense')
    and t.occurred_on >= m.month and t.occurred_on < (m.month + interval '1 month')
  group by m.month, c.currency_code
  order by c.currency_code, m.month;
$$;

-- Spending against each budget for one month. Expenses only; matching currency only.
create or replace function public.budget_progress(p_month date, p_include_archived boolean default false)
returns table (
  budget_id uuid,
  name text,
  category_id uuid,
  category_name text,
  currency_code text,
  limit_minor text,
  spent_minor text,
  alert_threshold_pct smallint,
  starts_on date,
  archived boolean,
  version bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select b.id, b.name, b.category_id, c.name, b.currency_code, b.limit_minor::text,
    coalesce((
      select sum(t.amount_minor) from public.transactions t
      where t.user_id = b.user_id and t.kind = 'expense' and t.currency_code = b.currency_code
        and t.occurred_on >= date_trunc('month', p_month)::date
        and t.occurred_on < (date_trunc('month', p_month) + interval '1 month')::date
        and (b.category_id is null or t.category_id = b.category_id)
    ), 0)::text,
    b.alert_threshold_pct, b.starts_on, b.archived_at is not null, b.version
  from public.budgets b
  left join public.transaction_categories c on c.id = b.category_id
  where (p_include_archived or b.archived_at is null)
  order by b.archived_at nulls first, b.name;
$$;

create or replace function public.budget_history(p_budget_id uuid, p_months integer, p_today date)
returns table (month date, spent_minor text, limit_minor text)
language sql
stable
security invoker
set search_path = ''
as $$
  with b as (select * from public.budgets where id = p_budget_id),
  months as (
    select generate_series(
      greatest((select starts_on from b),
        (date_trunc('month', p_today) - make_interval(months => greatest(1, least(p_months, 24)) - 1))::date),
      date_trunc('month', p_today)::date,
      interval '1 month')::date as month
  )
  select m.month,
    coalesce((
      select sum(t.amount_minor) from public.transactions t, b
      where t.kind = 'expense' and t.currency_code = b.currency_code
        and t.occurred_on >= m.month and t.occurred_on < (m.month + interval '1 month')
        and (b.category_id is null or t.category_id = b.category_id)
    ), 0)::text,
    (select limit_minor from b)::text
  from months m
  where exists (select 1 from b)
  order by m.month desc;
$$;

-- Searchable, filterable, sortable transaction list with names and total count.
create or replace function public.list_transactions(
  p_q text default null,
  p_kind text default null,
  p_account_id uuid default null,
  p_category_id uuid default null,
  p_from date default null,
  p_to date default null,
  p_sort text default 'date_desc',
  p_limit integer default 50,
  p_offset integer default 0
)
returns table (
  id uuid,
  kind text,
  account_id uuid,
  account_name text,
  transfer_account_id uuid,
  transfer_account_name text,
  amount_minor bigint,
  currency_code text,
  category_id uuid,
  category_name text,
  description text,
  merchant text,
  notes text,
  occurred_on date,
  version bigint,
  created_at timestamptz,
  updated_at timestamptz,
  total_count bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.id, t.kind, t.account_id, a.name, t.transfer_account_id, ta.name, t.amount_minor, t.currency_code,
    t.category_id, c.name, t.description, t.merchant, t.notes, t.occurred_on, t.version, t.created_at,
    t.updated_at, count(*) over ()
  from public.transactions t
  join public.financial_accounts a on a.id = t.account_id
  left join public.financial_accounts ta on ta.id = t.transfer_account_id
  left join public.transaction_categories c on c.id = t.category_id
  where (p_kind is null or t.kind = p_kind)
    and (p_account_id is null or t.account_id = p_account_id or t.transfer_account_id = p_account_id)
    and (p_category_id is null or t.category_id = p_category_id)
    and (p_from is null or t.occurred_on >= p_from)
    and (p_to is null or t.occurred_on <= p_to)
    and (
      p_q is null or btrim(p_q) = ''
      or position(lower(btrim(p_q)) in lower(
        coalesce(t.description, '') || ' ' || coalesce(t.merchant, '') || ' ' || coalesce(t.notes, '')
        || ' ' || coalesce(c.name, ''))) > 0
    )
  order by
    case when p_sort = 'amount_desc' then t.amount_minor end desc nulls last,
    case when p_sort = 'amount_asc' then t.amount_minor end asc nulls last,
    case when p_sort = 'date_asc' then t.occurred_on end asc nulls last,
    t.occurred_on desc, t.created_at desc
  limit greatest(1, least(p_limit, 200)) offset greatest(0, p_offset);
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.finance_summary(date, date)',
    'public.spending_by_category(date, date)',
    'public.monthly_cashflow(integer, date)',
    'public.budget_progress(date, boolean)',
    'public.budget_history(uuid, integer, date)',
    'public.list_transactions(text, text, uuid, uuid, date, date, text, integer, integer)'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end
$$;

-- >>> 20261102000100_walrus_memory.sql
-- =============================================================================
-- AVEN Stage 3 — Migration 8: Walrus Memory references
--
-- Walrus Memory (MemWal, Mainnet) is the long-term memory store. The memory
-- TEXT lives in Walrus, encrypted by the MemWal relayer. Supabase keeps only
-- the bookkeeping AVEN needs to run the integration safely:
--   * a short, non-sensitive LABEL for the memory list
--     (e.g. "Recommendation outcome · Food"), never the memory text itself;
--   * a SHA-256 content hash so identical memories are not written twice;
--   * the MemWal job id, job status and Walrus blob id;
--   * a short-lived OUTBOX copy of the text (pending_text) while the write is
--     queued or in flight, so a failed or rate-limited write can be retried.
--     It is erased as soon as Walrus confirms the memory (or it is forgotten),
--     which a CHECK constraint enforces;
--   * whether the user has SUPPRESSED the memory ("forget"). The MemWal SDK
--     has no delete call, so a suppressed blob is excluded from every recall
--     AVEN performs, and the limitation is disclosed before consent.
--
-- Users may only READ their rows. Rows are written by the AVEN server after it
-- talks to the MemWal relayer, so job ids, blob ids and statuses cannot be
-- forged from the browser.
-- =============================================================================

create table public.memory_records (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  category text not null check (
    category in (
      'memory_financial', 'memory_shared_expenses', 'memory_wellbeing',
      'memory_planning', 'memory_interactions'
    )
  ),
  kind text not null check (
    kind in (
      'recurring_expense', 'budgeting_style', 'overspending_category', 'savings_target',
      'savings_performance', 'goal_progress', 'income_pattern', 'subscription',
      'recommendation', 'recommendation_outcome', 'preference'
    )
  ),
  label text not null check (char_length(btrim(label)) between 1 and 160),
  content_hash text not null check (content_hash ~ '^[0-9a-f]{64}$'),
  source_refs jsonb not null default '[]'::jsonb check (jsonb_typeof(source_refs) = 'array'),
  supersedes uuid references public.memory_records (id) on delete set null,
  status text not null default 'queued' check (
    status in ('queued', 'submitted', 'stored', 'failed', 'suppressed')
  ),
  job_id text check (job_id is null or char_length(job_id) <= 200),
  job_status text check (
    job_status is null
    or job_status in ('pending', 'running', 'uploaded', 'done', 'failed', 'not_found')
  ),
  blob_id text check (blob_id is null or char_length(blob_id) <= 200),
  pending_text text check (pending_text is null or char_length(pending_text) <= 4000),
  attempts integer not null default 0 check (attempts between 0 and 100),
  last_error text check (last_error is null or char_length(last_error) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  submitted_at timestamptz,
  stored_at timestamptz,
  suppressed_at timestamptz,
  constraint memory_records_stored_has_blob check (status <> 'stored' or blob_id is not null),
  constraint memory_records_outbox_cleared check (
    status not in ('stored', 'suppressed') or pending_text is null
  ),
  constraint memory_records_suppressed_at check (
    (status = 'suppressed') = (suppressed_at is not null)
  )
);

-- One row per distinct memory text per user: re-deriving the same fact never
-- creates a second Walrus write.
create unique index memory_records_user_hash_uniq on public.memory_records (user_id, content_hash);
create index memory_records_user_status_idx on public.memory_records (user_id, status);
create index memory_records_user_kind_idx on public.memory_records (user_id, kind, created_at desc);
create index memory_records_blob_idx on public.memory_records (user_id, blob_id) where blob_id is not null;

create trigger memory_records_set_updated_at
  before update on public.memory_records
  for each row execute function private.set_updated_at();

-- A suppressed memory can never be revived, and ownership never changes.
create or replace function private.guard_memory_record_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.user_id <> old.user_id or new.content_hash <> old.content_hash then
    raise exception 'Memory ownership and content cannot change' using errcode = '42501';
  end if;
  if old.status = 'suppressed' and new.status <> 'suppressed' then
    raise exception 'A forgotten memory cannot be restored' using errcode = '22023';
  end if;
  return new;
end;
$$;

create trigger memory_records_guard_update
  before update on public.memory_records
  for each row execute function private.guard_memory_record_update();

alter table public.memory_records enable row level security;
revoke all on table public.memory_records from anon, authenticated;
grant select on table public.memory_records to authenticated;
create policy "Users can read their own memory records"
  on public.memory_records for select to authenticated
  using (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Make the financial memory category available, with a new policy version.
-- The consent screen shows the Walrus disclosures for this version, including
-- that memories cannot be deleted from Walrus through the MemWal SDK.
-- Other memory categories stay locked: their features do not exist yet.
-- -----------------------------------------------------------------------------
update public.consent_categories
  set is_available = true, policy_version = '2026-11-02'
  where category = 'memory_financial';

-- Revoking memory consent is recorded in the audit log by set_consent(). The
-- app stops writing and recalling immediately; existing Walrus memories are
-- only used again if consent is granted again.

-- >>> 20261102000200_sui_wallets.sql
-- =============================================================================
-- AVEN Stage 3 — Migration 9: Sui wallets (read-only) and confirmed imports
--
-- AVEN never holds keys, signs or sends anything. A user may add PUBLIC Sui
-- Mainnet addresses so AVEN can show on-chain balances and activity through
-- Tatum. On-chain data is displayed separately from AVEN's own records.
--
-- An on-chain transaction only becomes an AVEN transaction when the user
-- confirms it, and import_chain_transaction() refuses duplicates:
--   * the same digest can be imported once per user (unique constraint);
--   * a likely duplicate (same account, amount and date) needs explicit
--     confirmation from the user before it is created.
-- =============================================================================

create table public.sui_wallets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  network text not null default 'mainnet' check (network = 'mainnet'),
  address text not null check (address ~ '^0x[0-9a-f]{64}$'),
  label text check (label is null or char_length(btrim(label)) between 1 and 60),
  created_at timestamptz not null default now(),
  constraint sui_wallets_user_address_uniq unique (user_id, network, address)
);

create index sui_wallets_user_idx on public.sui_wallets (user_id);

-- At most 5 wallets per user (keeps provider usage predictable).
create or replace function private.guard_sui_wallet()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select count(*) from public.sui_wallets w where w.user_id = new.user_id) >= 5 then
      raise exception 'You can add up to 5 wallets' using errcode = '23514';
    end if;
  elsif new.user_id <> old.user_id or new.address <> old.address or new.network <> old.network then
    raise exception 'Only the wallet label can be changed' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger sui_wallets_guard
  before insert or update on public.sui_wallets
  for each row execute function private.guard_sui_wallet();

alter table public.sui_wallets enable row level security;
revoke all on table public.sui_wallets from anon, authenticated;
grant select, insert, delete on table public.sui_wallets to authenticated;
grant update (label) on table public.sui_wallets to authenticated;
create policy "Users can read their own wallets"
  on public.sui_wallets for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Users can add their own wallets"
  on public.sui_wallets for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "Users can rename their own wallets"
  on public.sui_wallets for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
create policy "Users can remove their own wallets"
  on public.sui_wallets for delete to authenticated
  using (user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Confirmed imports of on-chain transactions into AVEN's own records.
-- -----------------------------------------------------------------------------
create table public.chain_imports (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  wallet_id uuid references public.sui_wallets (id) on delete set null,
  network text not null default 'mainnet' check (network = 'mainnet'),
  tx_digest text not null check (tx_digest ~ '^[1-9A-HJ-NP-Za-km-z]{32,44}$'),
  -- Deleting the AVEN transaction removes the link, so it can be imported again.
  transaction_id uuid not null references public.transactions (id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint chain_imports_digest_uniq unique (user_id, network, tx_digest)
);

create index chain_imports_tx_idx on public.chain_imports (transaction_id);

alter table public.chain_imports enable row level security;
revoke all on table public.chain_imports from anon, authenticated;
grant select on table public.chain_imports to authenticated;
create policy "Users can read their own chain imports"
  on public.chain_imports for select to authenticated
  using (user_id = (select auth.uid()));

/**
 * Import one on-chain transaction as an AVEN transaction, atomically.
 * The finance write still goes through apply_finance_mutation(), so every
 * Stage 2 rule (ownership, currency, versioning, idempotency) applies.
 *
 * Returns jsonb:
 *   { status: 'imported', transaction_id }            on success
 *   { status: 'duplicate_digest', transaction_id }    already imported
 *   { status: 'possible_duplicate', matches: [...] }  needs p_confirm_duplicate
 *   { status: 'rejected', message }                   finance rules refused it
 */
create or replace function public.import_chain_transaction(
  p_mutation_id uuid,
  p_wallet_id uuid,
  p_tx_digest text,
  p_transaction_id uuid,
  p_payload jsonb,
  p_confirm_duplicate boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_existing uuid;
  v_matches jsonb;
  v_result jsonb;
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_tx_digest is null or p_tx_digest !~ '^[1-9A-HJ-NP-Za-km-z]{32,44}$' then
    raise exception 'Invalid transaction digest' using errcode = '22023';
  end if;
  if not exists (select 1 from public.sui_wallets w where w.id = p_wallet_id and w.user_id = v_user) then
    raise exception 'Wallet not found' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Invalid payload' using errcode = '22023';
  end if;

  -- Serialise imports of the same digest for this user.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text || ':sui:' || p_tx_digest, 0));

  select c.transaction_id into v_existing from public.chain_imports c
    where c.user_id = v_user and c.network = 'mainnet' and c.tx_digest = p_tx_digest;
  if v_existing is not null then
    return jsonb_build_object('status', 'duplicate_digest', 'transaction_id', v_existing);
  end if;

  if not coalesce(p_confirm_duplicate, false) then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', t.id, 'occurred_on', t.occurred_on, 'amount_minor', t.amount_minor,
             'description', t.description) order by t.occurred_on), '[]'::jsonb)
      into v_matches
      from public.transactions t
      where t.user_id = v_user
        and t.account_id = (p_payload ->> 'account_id')::uuid
        and t.amount_minor = (p_payload ->> 'amount_minor')::bigint
        and t.occurred_on between (p_payload ->> 'occurred_on')::date - 1
                              and (p_payload ->> 'occurred_on')::date + 1;
    if jsonb_array_length(v_matches) > 0 then
      return jsonb_build_object('status', 'possible_duplicate', 'matches', v_matches);
    end if;
  end if;

  v_result := public.apply_finance_mutation(
    p_mutation_id, 'transaction', 'create', p_transaction_id, p_payload, null, null);
  if v_result ->> 'status' <> 'applied' then
    return jsonb_build_object('status', 'rejected',
      'message', coalesce(v_result ->> 'message', 'The transaction could not be saved.'));
  end if;

  insert into public.chain_imports (user_id, wallet_id, tx_digest, transaction_id)
  values (v_user, p_wallet_id, p_tx_digest, p_transaction_id);

  perform private.write_audit(v_user, 'finance.chain_import',
    jsonb_build_object('network', 'mainnet', 'transaction_id', p_transaction_id));

  return jsonb_build_object('status', 'imported', 'transaction_id', p_transaction_id);
end;
$$;

revoke all on function public.import_chain_transaction(uuid, uuid, text, uuid, jsonb, boolean) from public, anon;
grant execute on function public.import_chain_transaction(uuid, uuid, text, uuid, jsonb, boolean) to authenticated;

