-- =============================================================================
-- AVEN Stage 4 — Migration 10: Recommendations and the user's decisions
--
-- Recommendations are produced by AVEN's deterministic intelligence engine
-- (src/lib/intelligence) from the user's own records plus memories recalled
-- from Walrus. This table is the INBOX: what was suggested this period and
-- how the user responded. It is not long-term memory — the decision is also
-- written to Walrus Memory (when the user has allowed memory), and the next
-- recommendations are shaped by what is RECALLED from Walrus.
--
-- Users may read their recommendations and create new open ones for
-- themselves (the engine runs with the user's session). Responses go through
-- respond_to_recommendation(), so a decision is recorded exactly once.
-- =============================================================================

create table public.recommendations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (
    kind in (
      'reduce_category_spend', 'set_category_budget', 'increase_savings',
      'review_subscription', 'goal_contribution'
    )
  ),
  -- kind + subject + period, e.g. "reduce_category_spend:<category id>:2026-11"
  dedupe_key text not null check (char_length(dedupe_key) between 3 and 200),
  period text not null check (period ~ '^\d{4}-\d{2}$'),
  title text not null check (char_length(btrim(title)) between 1 and 160),
  explanation text not null check (char_length(explanation) between 1 and 2000),
  currency_code text not null references public.currencies (code),
  suggested_minor bigint check (
    suggested_minor is null or (suggested_minor >= 0 and suggested_minor <= private.max_amount_minor())
  ),
  category_id uuid references public.transaction_categories (id) on delete set null,
  goal_id uuid references public.savings_goals (id) on delete set null,
  -- The numbers the engine used (deterministic, re-checkable).
  evidence jsonb not null default '{}'::jsonb check (
    jsonb_typeof(evidence) = 'object' and pg_column_size(evidence) <= 8192
  ),
  -- Which recalled Walrus memories changed this recommendation, and how.
  memory_influence jsonb not null default '[]'::jsonb check (
    jsonb_typeof(memory_influence) = 'array' and pg_column_size(memory_influence) <= 8192
  ),
  status text not null default 'open' check (status in ('open', 'accepted', 'rejected', 'modified')),
  response_minor bigint check (
    response_minor is null or (response_minor >= 0 and response_minor <= private.max_amount_minor())
  ),
  response_note text check (response_note is null or char_length(response_note) <= 300),
  responded_at timestamptz,
  outcome_memory_id uuid references public.memory_records (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint recommendations_dedupe_uniq unique (user_id, dedupe_key),
  constraint recommendations_response_shape check (
    (status = 'open' and responded_at is null)
    or (status <> 'open' and responded_at is not null)
  ),
  constraint recommendations_modified_value check (status <> 'modified' or response_minor is not null)
);

create index recommendations_user_status_idx on public.recommendations (user_id, status, created_at desc);

alter table public.recommendations enable row level security;
revoke all on table public.recommendations from anon, authenticated;
grant select on table public.recommendations to authenticated;
grant insert (
  user_id, kind, dedupe_key, period, title, explanation, currency_code, suggested_minor,
  category_id, goal_id, evidence, memory_influence
) on table public.recommendations to authenticated;
create policy "Users can read their own recommendations"
  on public.recommendations for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Users can create their own open recommendations"
  on public.recommendations for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'open');

-- Linked category/goal must belong to the same user.
create or replace function private.guard_recommendation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.category_id is not null and not exists (
    select 1 from public.transaction_categories c where c.id = new.category_id and c.user_id = new.user_id
  ) then
    raise exception 'Category not found' using errcode = '42501';
  end if;
  if new.goal_id is not null and not exists (
    select 1 from public.savings_goals g where g.id = new.goal_id and g.user_id = new.user_id
  ) then
    raise exception 'Goal not found' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger recommendations_guard
  before insert on public.recommendations
  for each row execute function private.guard_recommendation();

/**
 * Records the user's decision on an open recommendation, once.
 * p_action: 'accepted' | 'rejected' | 'modified' (modified needs p_value_minor).
 * Returns the updated row as jsonb, or raises if it was already answered.
 */
create or replace function public.respond_to_recommendation(
  p_id uuid,
  p_action text,
  p_value_minor bigint default null,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_row public.recommendations%rowtype;
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_action not in ('accepted', 'rejected', 'modified') then
    raise exception 'Invalid response' using errcode = '22023';
  end if;
  if p_action = 'modified' and (p_value_minor is null or p_value_minor < 0) then
    raise exception 'A modified response needs an amount' using errcode = '22023';
  end if;
  if p_note is not null and char_length(p_note) > 300 then
    raise exception 'Note is too long' using errcode = '22023';
  end if;

  update public.recommendations r
    set status = p_action,
        response_minor = case when p_action = 'modified' then p_value_minor else null end,
        response_note = nullif(btrim(coalesce(p_note, '')), ''),
        responded_at = now()
    where r.id = p_id and r.user_id = v_user and r.status = 'open'
    returning * into v_row;

  if not found then
    if exists (select 1 from public.recommendations r where r.id = p_id and r.user_id = v_user) then
      raise exception 'This recommendation has already been answered' using errcode = '55000';
    end if;
    raise exception 'Recommendation not found' using errcode = '42501';
  end if;

  perform private.write_audit(v_user, 'intelligence.recommendation_answered',
    jsonb_build_object('kind', v_row.kind, 'response', p_action));
  return to_jsonb(v_row);
end;
$$;

revoke all on function public.respond_to_recommendation(uuid, text, bigint, text) from public, anon;
grant execute on function public.respond_to_recommendation(uuid, text, bigint, text) to authenticated;

-- >>> 20261104000100_planning_wellbeing_tables.sql
-- =============================================================================
-- AVEN Stage 5 — Migration 11: Planning and Wellbeing tables
--
-- Same rules as finance (docs/DATABASE.md):
--   * ids are generated by the client (so records can be created offline);
--   * users may only READ these tables — every write goes through
--     public.apply_life_mutation() (next migration): idempotent receipts,
--     optimistic versions, ownership checks, wellbeing consent;
--   * triggers re-check cross-table ownership whatever the write path.
--
-- Wellbeing records are sensitive. They can only be written while the user
-- has granted the `wellbeing_data` consent (checked in apply_life_mutation),
-- are visible only to their owner (RLS), and are never sent to Walrus Memory
-- without the separate `memory_wellbeing` consent.
-- =============================================================================

-- Generic guard: a referenced row (TG_ARGV[0] table, TG_ARGV[1] column) must
-- belong to the same user as the new row.
create or replace function private.guard_owned_ref()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_ok boolean;
  v_ref uuid;
begin
  execute format('select ($1).%I', tg_argv[1]) into v_ref using new;
  if v_ref is null then
    return new;
  end if;
  execute format('select exists (select 1 from public.%I where id = $1 and user_id = $2)', tg_argv[0])
    into v_ok using v_ref, new.user_id;
  if not v_ok then
    raise exception 'Referenced record not found' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace function private.guard_user_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.user_id <> old.user_id or new.id <> old.id then
    raise exception 'Ownership cannot change' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: task categories and tasks
-- -----------------------------------------------------------------------------
create table public.task_categories (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 40),
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index task_categories_user_idx on public.task_categories (user_id);
create unique index task_categories_active_name_uniq
  on public.task_categories (user_id, lower(btrim(name))) where archived_at is null;

create table public.tasks (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 200),
  description text check (description is null or char_length(description) <= 2000),
  status text not null default 'not_started'
    check (status in ('not_started', 'in_progress', 'completed', 'cancelled')),
  priority text not null default 'medium' check (priority in ('low', 'medium', 'high')),
  category_id uuid references public.task_categories (id) on delete set null,
  -- Due date/time are LOCAL to the user's time zone; remind_at is an exact instant.
  due_on date,
  due_time time,
  remind_at timestamptz,
  completed_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (due_time is null or due_on is not null),
  check ((status = 'completed') = (completed_at is not null))
);
create index tasks_user_status_idx on public.tasks (user_id, status, due_on);
create index tasks_user_remind_idx on public.tasks (user_id, remind_at) where remind_at is not null;

-- completed_at follows the status, so it can never be forged or forgotten.
create or replace function private.task_completion()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'completed' then
    new.completed_at := case
      when tg_op = 'UPDATE' and old.status = 'completed' then old.completed_at
      else now() end;
  else
    new.completed_at := null;
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: calendar events (recurrence is expanded on read, never stored as
-- copies — so recurring events cannot produce duplicate records)
-- -----------------------------------------------------------------------------
create table public.calendar_events (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 200),
  description text check (description is null or char_length(description) <= 2000),
  category text not null default 'personal'
    check (category in ('personal', 'work', 'health', 'finance', 'social', 'learning', 'other')),
  all_day boolean not null default false,
  -- Timed events: exact instants.
  starts_at timestamptz,
  ends_at timestamptz,
  -- All-day events: local dates (inclusive).
  start_date date,
  end_date date,
  -- The zone the event's wall-clock times (and recurrence) belong to.
  time_zone text not null check (char_length(time_zone) between 1 and 64),
  recurrence text check (recurrence in ('daily', 'weekly', 'monthly', 'yearly')),
  recurrence_interval smallint not null default 1 check (recurrence_interval between 1 and 99),
  -- 0 = Sunday … 6 = Saturday (weekly recurrence only).
  recurrence_weekdays smallint[] check (
    recurrence_weekdays is null
    or (cardinality(recurrence_weekdays) between 1 and 7 and recurrence_weekdays <@ array[0,1,2,3,4,5,6]::smallint[])
  ),
  recurrence_until date,
  reminder_minutes integer check (reminder_minutes is null or reminder_minutes between 0 and 10080),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (all_day and start_date is not null and end_date is not null and end_date >= start_date
      and end_date - start_date <= 31 and starts_at is null and ends_at is null)
    or (not all_day and starts_at is not null and ends_at is not null and ends_at >= starts_at
      and ends_at - starts_at <= interval '14 days' and start_date is null and end_date is null)
  ),
  check (recurrence is not null or (recurrence_weekdays is null and recurrence_until is null)),
  check (recurrence_weekdays is null or recurrence = 'weekly')
);
create index calendar_events_user_start_idx on public.calendar_events (user_id, starts_at);
create index calendar_events_user_date_idx on public.calendar_events (user_id, start_date);
create index calendar_events_user_recurring_idx on public.calendar_events (user_id) where recurrence is not null;

create trigger calendar_events_validate_time_zone
  before insert or update of time_zone on public.calendar_events
  for each row execute function private.validate_time_zone();

-- One exception per occurrence of a recurring event: cancelled, or moved/renamed.
create table public.calendar_event_exceptions (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  event_id uuid not null references public.calendar_events (id) on delete cascade,
  -- The LOCAL date the occurrence would originally have started on.
  occurrence_date date not null,
  cancelled boolean not null default true,
  starts_at timestamptz,
  ends_at timestamptz,
  title text check (title is null or char_length(btrim(title)) between 1 and 200),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint calendar_event_exceptions_occurrence_uniq unique (event_id, occurrence_date),
  check (cancelled or (starts_at is not null and ends_at is not null and ends_at >= starts_at))
);
create index calendar_event_exceptions_user_idx on public.calendar_event_exceptions (user_id);

create or replace function private.guard_event_exception()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.calendar_events e
    where e.id = new.event_id and e.user_id = new.user_id and e.recurrence is not null
  ) then
    raise exception 'Recurring event not found' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: habits and dated check-ins
-- -----------------------------------------------------------------------------
create table public.habits (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  description text check (description is null or char_length(description) <= 500),
  category text not null default 'routine' check (
    category in ('health', 'fitness', 'mind', 'learning', 'finance', 'sleep', 'hydration', 'routine', 'other')
  ),
  frequency text not null default 'daily' check (frequency in ('daily', 'specific_days')),
  weekdays smallint[] check (
    weekdays is null
    or (cardinality(weekdays) between 1 and 7 and weekdays <@ array[0,1,2,3,4,5,6]::smallint[])
  ),
  start_on date not null,
  end_on date,
  reminder_time time,
  time_zone text not null check (char_length(time_zone) between 1 and 64),
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_on is null or end_on >= start_on),
  check ((frequency = 'specific_days') = (weekdays is not null))
);
create index habits_user_idx on public.habits (user_id) where archived_at is null;

create trigger habits_validate_time_zone
  before insert or update of time_zone on public.habits
  for each row execute function private.validate_time_zone();

create table public.habit_check_ins (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  habit_id uuid not null references public.habits (id) on delete cascade,
  on_date date not null,
  status text not null default 'done' check (status in ('done', 'skipped')),
  note text check (note is null or char_length(note) <= 300),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint habit_check_ins_day_uniq unique (habit_id, on_date)
);
create index habit_check_ins_user_date_idx on public.habit_check_ins (user_id, on_date);

-- A check-in must be for the user's own habit, inside its active period, and
-- not in the future (in the habit's time zone).
create or replace function private.guard_habit_check_in()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_habit public.habits%rowtype;
begin
  select * into v_habit from public.habits h where h.id = new.habit_id and h.user_id = new.user_id;
  if not found then
    raise exception 'Habit not found' using errcode = '42501';
  end if;
  if new.on_date < v_habit.start_on or (v_habit.end_on is not null and new.on_date > v_habit.end_on) then
    raise exception 'That date is outside this habit''s schedule' using errcode = '22023';
  end if;
  if new.on_date > (now() at time zone v_habit.time_zone)::date then
    raise exception 'You can''t check in for a future day' using errcode = '22023';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: private daily and weekly reviews
-- -----------------------------------------------------------------------------
create table public.reviews (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('daily', 'weekly')),
  -- Daily: the day. Weekly: the first day of the week.
  period_start date not null,
  highlights text check (highlights is null or char_length(highlights) <= 4000),
  missed text check (missed is null or char_length(missed) <= 4000),
  next_focus text check (next_focus is null or char_length(next_focus) <= 4000),
  notes text check (notes is null or char_length(notes) <= 8000),
  rating smallint check (rating is null or rating between 1 and 5),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint reviews_period_uniq unique (user_id, kind, period_start)
);

create table public.planning_preferences (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  daily_review_enabled boolean not null default true,
  daily_review_time time not null default '20:30',
  weekly_review_enabled boolean not null default true,
  weekly_review_day smallint not null default 0 check (weekly_review_day between 0 and 6),
  weekly_review_time time not null default '18:00',
  -- Include a "review your finances" step (links to Money; no finance data is copied).
  weekly_finance_review boolean not null default true,
  updated_at timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Wellbeing
-- -----------------------------------------------------------------------------
create table public.wellbeing_preferences (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  water_unit text not null default 'ml' check (water_unit in ('ml', 'l', 'fl_oz')),
  water_target_ml integer not null default 2000 check (water_target_ml between 250 and 10000),
  distance_unit text not null default 'km' check (distance_unit in ('km', 'mi')),
  sleep_target_minutes smallint not null default 480 check (sleep_target_minutes between 180 and 900),
  updated_at timestamptz not null default now()
);

create table public.sleep_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  -- Exact instants, so overnight sleep and daylight-saving changes are handled
  -- by subtraction; wake_date is the user's LOCAL date of waking.
  slept_at timestamptz not null,
  woke_at timestamptz not null,
  wake_date date not null,
  duration_minutes integer generated always as ((extract(epoch from (woke_at - slept_at)) / 60)::integer) stored,
  quality smallint check (quality is null or quality between 1 and 5),
  note text check (note is null or char_length(note) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (woke_at > slept_at and woke_at - slept_at <= interval '20 hours')
);
create index sleep_logs_user_date_idx on public.sleep_logs (user_id, wake_date);

create table public.water_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  -- Always stored in millilitres; shown in the user's chosen unit.
  amount_ml integer not null check (amount_ml between 1 and 5000),
  logged_at timestamptz not null,
  local_date date not null,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index water_logs_user_date_idx on public.water_logs (user_id, local_date);

create table public.meal_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  meal_type text not null check (meal_type in ('breakfast', 'lunch', 'dinner', 'snack')),
  description text not null check (char_length(btrim(description)) between 1 and 300),
  eaten_at timestamptz not null,
  local_date date not null,
  note text check (note is null or char_length(note) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index meal_logs_user_date_idx on public.meal_logs (user_id, local_date);

create table public.activity_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  activity_type text not null check (
    activity_type in ('walking', 'running', 'cycling', 'gym', 'swimming', 'sports', 'home_workout', 'other')
  ),
  duration_minutes integer not null check (duration_minutes between 1 and 1440),
  -- Always stored in metres; shown in km or miles.
  distance_m integer check (distance_m is null or distance_m between 0 and 1000000),
  intensity text check (intensity is null or intensity in ('light', 'moderate', 'vigorous')),
  on_date date not null,
  note text check (note is null or char_length(note) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index activity_logs_user_date_idx on public.activity_logs (user_id, on_date);

-- Mood, energy and stress check-ins. Pulse Check entries are stored here too
-- (source = 'pulse_check'), so there is exactly one place for how you feel.
create table public.mood_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  logged_at timestamptz not null,
  local_date date not null,
  mood smallint check (mood is null or mood between 1 and 5),
  energy smallint check (energy is null or energy between 1 and 5),
  stress smallint check (stress is null or stress between 1 and 5),
  sleep_rating smallint check (sleep_rating is null or sleep_rating between 1 and 5),
  day_rating smallint check (day_rating is null or day_rating between 1 and 5),
  note text check (note is null or char_length(note) <= 1000),
  source text not null default 'wellbeing' check (source in ('wellbeing', 'pulse_check')),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (num_nonnulls(mood, energy, stress, sleep_rating, day_rating, note) > 0)
);
create index mood_logs_user_date_idx on public.mood_logs (user_id, local_date);

-- -----------------------------------------------------------------------------
-- Shared triggers and access for every record table above
-- -----------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'task_categories', 'tasks', 'calendar_events', 'calendar_event_exceptions', 'habits',
    'habit_check_ins', 'reviews', 'sleep_logs', 'water_logs', 'meal_logs', 'activity_logs', 'mood_logs'
  ] loop
    execute format('create trigger %I before update on public.%I for each row execute function private.bump_version()', t || '_bump_version', t);
    execute format('create trigger %I before update on public.%I for each row execute function private.guard_user_immutable()', t || '_guard_owner', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select on table public.%I to authenticated', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      'Users can read their own ' || replace(t, '_', ' '), t);
    execute format('create index if not exists %I on public.%I (user_id)', t || '_owner_idx', t);
  end loop;
end;
$$;

create trigger tasks_completion before insert or update of status on public.tasks
  for each row execute function private.task_completion();
create trigger tasks_category_owner before insert or update of category_id on public.tasks
  for each row execute function private.guard_owned_ref('task_categories', 'category_id');
create trigger calendar_event_exceptions_guard before insert or update of event_id on public.calendar_event_exceptions
  for each row execute function private.guard_event_exception();
create trigger habit_check_ins_guard before insert or update of habit_id, on_date on public.habit_check_ins
  for each row execute function private.guard_habit_check_in();

-- Preferences: one row per user, created on first save; owner read/insert/update.
do $$
declare
  t text;
begin
  foreach t in array array['planning_preferences', 'wellbeing_preferences'] loop
    execute format('create trigger %I before update on public.%I for each row execute function private.set_updated_at()', t || '_set_updated_at', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select, insert, update on table public.%I to authenticated', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))', 'Users can read their own ' || replace(t, '_', ' '), t);
    execute format('create policy %I on public.%I for insert to authenticated with check (user_id = (select auth.uid()))', 'Users can create their own ' || replace(t, '_', ' '), t);
    execute format('create policy %I on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', 'Users can update their own ' || replace(t, '_', ' '), t);
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Consent: wellbeing records and planning/wellbeing memory become available.
-- -----------------------------------------------------------------------------
update public.consent_categories
  set is_available = true, policy_version = '2026-11-04'
  where category in ('wellbeing_data', 'memory_wellbeing', 'memory_planning');

-- >>> 20261104000200_life_mutations_events.sql
-- =============================================================================
-- AVEN Stage 5 — Migration 12: the planning/wellbeing write path and life events
--
-- public.apply_life_mutation() is the ONLY way planning and wellbeing records
-- are written (online, and from the offline outbox through /api/sync). Like
-- apply_finance_mutation() it:
--   1. takes the user from the session (auth.uid()), never from input;
--   2. serialises duplicate deliveries and replays the stored receipt;
--   3. allows only listed entities, operations and columns;
--   4. checks optimistic versions on update/delete (never overwrites);
--   5. refuses wellbeing writes without the `wellbeing_data` consent
--      (deleting your own wellbeing data is always allowed);
--   6. records one de-duplicated life_event per meaningful change, for the
--      Nudge Center and summaries to consume.
-- =============================================================================

-- Which entities exist, the table behind each, and the columns a payload may set.
create table private.life_entities (
  entity text primary key,
  table_name text not null,
  columns text[] not null,
  wellbeing boolean not null default false,
  operations text[] not null default array['create', 'update', 'delete']
);

insert into private.life_entities (entity, table_name, columns, wellbeing, operations) values
  ('task_category', 'task_categories', array['name'], false, array['create', 'update']),
  ('task', 'tasks', array['title', 'description', 'status', 'priority', 'category_id', 'due_on', 'due_time', 'remind_at'], false, array['create', 'update', 'delete']),
  ('calendar_event', 'calendar_events', array['title', 'description', 'category', 'all_day', 'starts_at', 'ends_at', 'start_date', 'end_date', 'time_zone', 'recurrence', 'recurrence_interval', 'recurrence_weekdays', 'recurrence_until', 'reminder_minutes'], false, array['create', 'update', 'delete']),
  ('calendar_event_exception', 'calendar_event_exceptions', array['event_id', 'occurrence_date', 'cancelled', 'starts_at', 'ends_at', 'title'], false, array['create', 'update', 'delete']),
  ('habit', 'habits', array['name', 'description', 'category', 'frequency', 'weekdays', 'start_on', 'end_on', 'reminder_time', 'time_zone'], false, array['create', 'update', 'delete']),
  ('habit_check_in', 'habit_check_ins', array['habit_id', 'on_date', 'status', 'note'], false, array['create', 'update', 'delete']),
  ('review', 'reviews', array['kind', 'period_start', 'highlights', 'missed', 'next_focus', 'notes', 'rating'], false, array['create', 'update', 'delete']),
  ('sleep_log', 'sleep_logs', array['slept_at', 'woke_at', 'wake_date', 'quality', 'note'], true, array['create', 'update', 'delete']),
  ('water_log', 'water_logs', array['amount_ml', 'logged_at', 'local_date'], true, array['create', 'update', 'delete']),
  ('meal_log', 'meal_logs', array['meal_type', 'description', 'eaten_at', 'local_date', 'note'], true, array['create', 'update', 'delete']),
  ('activity_log', 'activity_logs', array['activity_type', 'duration_minutes', 'distance_m', 'intensity', 'on_date', 'note'], true, array['create', 'update', 'delete']),
  ('mood_log', 'mood_logs', array['logged_at', 'local_date', 'mood', 'energy', 'stress', 'sleep_rating', 'day_rating', 'note', 'source'], true, array['create', 'update', 'delete']);

revoke all on table private.life_entities from public;

-- -----------------------------------------------------------------------------
-- Life events: de-duplicated facts other modules consume (Nudge Center,
-- summaries). Producers never notify anyone directly.
-- -----------------------------------------------------------------------------
create table public.life_events (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (
    kind in ('task_completed', 'habit_checked_in', 'review_saved', 'wellbeing_logged', 'event_scheduled')
  ),
  dedupe_key text not null check (char_length(dedupe_key) between 1 and 200),
  payload jsonb not null default '{}'::jsonb check (jsonb_typeof(payload) = 'object' and pg_column_size(payload) <= 2048),
  occurred_at timestamptz not null default now(),
  processed_at timestamptz,
  constraint life_events_dedupe_uniq unique (user_id, dedupe_key)
);
create index life_events_unprocessed_idx on public.life_events (occurred_at) where processed_at is null;

alter table public.life_events enable row level security;
revoke all on table public.life_events from anon, authenticated;
grant select on table public.life_events to authenticated;
create policy "Users can read their own life events"
  on public.life_events for select to authenticated
  using (user_id = (select auth.uid()));

create or replace function private.record_life_event(p_user uuid, p_kind text, p_key text, p_payload jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.life_events (user_id, kind, dedupe_key, payload)
  values (p_user, p_kind, p_key, coalesce(p_payload, '{}'::jsonb))
  on conflict (user_id, dedupe_key) do nothing;
$$;
revoke all on function private.record_life_event(uuid, text, text, jsonb) from public;

-- -----------------------------------------------------------------------------
-- The write path
-- -----------------------------------------------------------------------------
create or replace function private.life_apply(
  p_user uuid, p_cfg private.life_entities, p_op text, p_id uuid, p jsonb, p_base bigint
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cols text;
  v_vals text;
  v_version bigint;
  v_record jsonb;
  v_exists boolean;
begin
  select string_agg(format('%I', c), ', '), string_agg(format('r.%I', c), ', ')
    into v_cols, v_vals
    from unnest(p_cfg.columns) c where p ? c;

  if p_op = 'create' then
    execute format('select exists (select 1 from public.%I where id = $1)', p_cfg.table_name)
      into v_exists using p_id;
    if v_exists then
      -- Never reveal whether an id belongs to someone else.
      raise exception 'Not found' using errcode = '42501';
    end if;
    execute format(
      'insert into public.%1$I as t (id, user_id%2$s) select $1, $2%3$s from jsonb_populate_record(null::public.%1$I, $3) r returning to_jsonb(t)',
      p_cfg.table_name,
      case when v_cols is null then '' else ', ' || v_cols end,
      case when v_vals is null then '' else ', ' || v_vals end)
      into v_record using p_id, p_user, p;
    return private.result('applied', jsonb_build_object('server_version', (v_record ->> 'version')::bigint, 'record', v_record));
  end if;

  execute format('select version, to_jsonb(t) from public.%I t where id = $1 and user_id = $2 for update', p_cfg.table_name)
    into v_version, v_record using p_id, p_user;
  if v_version is null then
    return private.result('conflict', jsonb_build_object('reason', 'not_found', 'message', 'This item no longer exists.'));
  end if;
  if p_base is null or p_base <> v_version then
    return private.result('conflict', jsonb_build_object('reason', 'version',
      'message', 'This item was changed somewhere else.', 'server_version', v_version, 'record', v_record));
  end if;

  if p_op = 'delete' then
    execute format('delete from public.%I where id = $1 and user_id = $2', p_cfg.table_name) using p_id, p_user;
    return private.result('applied', jsonb_build_object('server_version', v_version, 'deleted', true));
  end if;

  -- update: only the listed columns that are present in the payload change.
  if v_cols is not null then
    execute format(
      'update public.%1$I as t set (%2$s) = (select %3$s from jsonb_populate_record(t, $3) r) where t.id = $1 and t.user_id = $2 returning to_jsonb(t)',
      p_cfg.table_name, v_cols, v_vals)
      into v_record using p_id, p_user, p;
  end if;
  if p ? 'archived' and p_cfg.table_name in ('task_categories', 'habits') then
    execute format(
      'update public.%I as t set archived_at = case when ($3 ->> ''archived'')::boolean then coalesce(archived_at, now()) else null end where t.id = $1 and t.user_id = $2 returning to_jsonb(t)',
      p_cfg.table_name)
      into v_record using p_id, p_user, p;
  elsif v_cols is null then
    execute format('update public.%I as t set updated_at = now() where t.id = $1 and t.user_id = $2 returning to_jsonb(t)', p_cfg.table_name)
      into v_record using p_id, p_user;
  end if;
  return private.result('applied', jsonb_build_object('server_version', (v_record ->> 'version')::bigint, 'record', v_record));
end;
$$;
revoke all on function private.life_apply(uuid, private.life_entities, text, uuid, jsonb, bigint) from public;

create or replace function public.apply_life_mutation(
  p_mutation_id uuid,
  p_entity text,
  p_operation text,
  p_record_id uuid,
  p_payload jsonb,
  p_base_version bigint default null,
  p_device_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_cfg private.life_entities%rowtype;
  v_existing jsonb;
  v_result jsonb;
  v_device uuid;
  v_message text;
  v_record jsonb;
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_mutation_id is null or p_record_id is null then
    raise exception 'Mutation and record ids are required' using errcode = '22023';
  end if;
  select * into v_cfg from private.life_entities where entity = p_entity;
  if not found or not (p_operation = any (v_cfg.operations)) then
    raise exception 'Unsupported mutation: % %', p_entity, p_operation using errcode = '22023';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' or pg_column_size(p_payload) > 16384 then
    raise exception 'Invalid payload' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text || ':' || p_mutation_id::text, 0));
  select r.response into v_existing
  from public.sync_receipts r
  where r.user_id = v_user and r.client_mutation_id = p_mutation_id;
  if found then
    return coalesce(v_existing, private.result('applied')) || jsonb_build_object('replayed', true);
  end if;

  if p_device_id is not null then
    insert into public.user_devices (id, user_id) values (p_device_id, v_user)
    on conflict (id) do update set last_seen_at = now(), last_sync_at = now()
      where public.user_devices.user_id = v_user;
    select id into v_device from public.user_devices where id = p_device_id and user_id = v_user;
  end if;

  if v_cfg.wellbeing and p_operation <> 'delete' and not exists (
    select 1 from public.consent_state s
    where s.user_id = v_user and s.category = 'wellbeing_data' and s.granted
  ) then
    v_result := private.result('rejected', jsonb_build_object('reason', 'consent',
      'message', 'Allow "Store wellbeing information" in Settings → Privacy to save wellbeing records.'));
  else
    begin
      v_result := private.life_apply(v_user, v_cfg, p_operation, p_record_id, p_payload, p_base_version);
    exception
      when insufficient_privilege then
        v_result := private.result('rejected', jsonb_build_object('message', 'Not found.'));
      when unique_violation then
        v_result := private.result('rejected', jsonb_build_object('reason', 'exists',
          'message', 'That already exists (for example, a second check-in for the same day).'));
      when check_violation or not_null_violation or foreign_key_violation then
        v_result := private.result('rejected', jsonb_build_object('message', 'Some of the details are not valid.'));
      when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format
        or datetime_field_overflow or invalid_parameter_value or raise_exception
        or array_subscript_error or datatype_mismatch or invalid_time_zone_displacement_value then
        get stacked diagnostics v_message = message_text;
        v_result := private.result('rejected', jsonb_build_object('message', left(v_message, 200)));
    end;
  end if;

  insert into public.sync_receipts (
    user_id, client_mutation_id, device_id, entity, record_id, operation, result, server_version, response
  ) values (
    v_user, p_mutation_id, v_device, p_entity, p_record_id, p_operation,
    v_result ->> 'status', (v_result ->> 'server_version')::bigint, v_result
  );

  -- Life events for other modules (de-duplicated by key).
  if v_result ->> 'status' = 'applied' and p_operation <> 'delete' then
    v_record := v_result -> 'record';
    if p_entity = 'task' and v_record ->> 'status' = 'completed' then
      perform private.record_life_event(v_user, 'task_completed', 'task_completed:' || p_record_id,
        jsonb_build_object('task_id', p_record_id));
    elsif p_entity = 'habit_check_in' and v_record ->> 'status' = 'done' then
      perform private.record_life_event(v_user, 'habit_checked_in',
        'habit_checked_in:' || (v_record ->> 'habit_id') || ':' || (v_record ->> 'on_date'),
        jsonb_build_object('habit_id', v_record ->> 'habit_id', 'on_date', v_record ->> 'on_date'));
    elsif p_entity = 'review' then
      perform private.record_life_event(v_user, 'review_saved',
        'review_saved:' || (v_record ->> 'kind') || ':' || (v_record ->> 'period_start'),
        jsonb_build_object('kind', v_record ->> 'kind', 'period_start', v_record ->> 'period_start'));
    elsif v_cfg.wellbeing and p_operation = 'create' then
      perform private.record_life_event(v_user, 'wellbeing_logged', 'wellbeing_logged:' || p_record_id,
        jsonb_build_object('entity', p_entity));
    end if;
  end if;
  return v_result;
end;
$$;
revoke all on function public.apply_life_mutation(uuid, text, text, uuid, jsonb, bigint, uuid) from public, anon;
grant execute on function public.apply_life_mutation(uuid, text, text, uuid, jsonb, bigint, uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- Nudge Center: in-app notifications
-- -----------------------------------------------------------------------------
-- A category for memory-supported suggestions, which users can turn off.
alter table public.notification_category_preferences
  drop constraint notification_category_preferences_category_check;
alter table public.notification_category_preferences
  add constraint notification_category_preferences_category_check check (category in (
    'subscriptions', 'shared_expenses', 'budgets', 'savings',
    'routines', 'wellbeing', 'planning', 'account_security', 'suggestions'
  ));

insert into public.notification_category_preferences (user_id, category, frequency)
select p.id, 'suggestions', 'daily_digest' from public.profiles p
on conflict (user_id, category) do nothing;

create or replace function private.seed_suggestion_preferences()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.notification_category_preferences (user_id, category, frequency)
  values (new.id, 'suggestions', 'daily_digest')
  on conflict (user_id, category) do nothing;
  return new;
end;
$$;
revoke all on function private.seed_suggestion_preferences() from public;
create trigger on_profile_created_seed_suggestions
  after insert on public.profiles
  for each row execute function private.seed_suggestion_preferences();

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  category text not null check (category in (
    'subscriptions', 'shared_expenses', 'budgets', 'savings',
    'routines', 'wellbeing', 'planning', 'account_security', 'suggestions'
  )),
  kind text not null check (kind in (
    'task_reminder', 'task_due', 'event_reminder', 'habit_reminder', 'habit_missed',
    'habit_streak', 'review_due', 'daily_summary', 'weekly_summary', 'budget_threshold',
    'budget_exceeded', 'savings_milestone', 'suggestion'
  )),
  priority text not null default 'normal' check (priority in ('low', 'normal', 'high')),
  title text not null check (char_length(btrim(title)) between 1 and 120),
  body text check (body is null or char_length(body) <= 2000),
  -- Internal links only (never an external URL).
  action_url text check (action_url is null or action_url ~ '^/[A-Za-z0-9/_?=&.%-]*$'),
  related_type text check (related_type is null or related_type ~ '^[a-z_]{1,40}$'),
  related_id uuid,
  -- One notification per occurrence: the scheduler can run any number of times.
  dedupe_key text not null check (char_length(dedupe_key) between 1 and 200),
  -- delivered: visible now · scheduled: waiting (quiet hours) · bundled: only in
  -- a summary · suppressed: blocked by the user's preferences (kept as history).
  status text not null check (status in ('delivered', 'scheduled', 'bundled', 'suppressed')),
  decision_reason text check (decision_reason is null or char_length(decision_reason) <= 60),
  digest text check (digest is null or digest in ('daily', 'weekly')),
  scheduled_for timestamptz,
  delivered_at timestamptz,
  read_at timestamptz,
  dismissed_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  constraint notifications_dedupe_uniq unique (user_id, dedupe_key),
  check (status <> 'delivered' or delivered_at is not null),
  check (status <> 'scheduled' or scheduled_for is not null)
);
create index notifications_user_feed_idx on public.notifications (user_id, status, created_at desc);
create index notifications_due_idx on public.notifications (scheduled_for) where status = 'scheduled';

alter table public.notifications enable row level security;
revoke all on table public.notifications from anon, authenticated;
grant select on table public.notifications to authenticated;
-- Users may only mark their notifications read/unread or dismiss them.
grant update (read_at, dismissed_at) on table public.notifications to authenticated;
create policy "Users can read their own notifications"
  on public.notifications for select to authenticated
  using (user_id = (select auth.uid()));
create policy "Users can mark their own notifications"
  on public.notifications for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Server-side scheduler runs (no user access).
create table public.scheduler_runs (
  id bigint generated always as identity primary key,
  trigger_source text not null check (trigger_source in ('cron', 'github_actions', 'vercel_cron', 'manual', 'catch_up')),
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  users_processed integer not null default 0,
  notifications_created integer not null default 0,
  error text check (error is null or char_length(error) <= 500)
);
alter table public.scheduler_runs enable row level security;
revoke all on table public.scheduler_runs from anon, authenticated;

-- Signed-in users may see WHEN the background scheduler last ran (no counts,
-- no other users' data), so the Nudge Center can say if reminders are flowing.
create function public.scheduler_status()
returns table (last_run_at timestamptz, last_run_ok boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select r.started_at, r.error is null and r.finished_at is not null
  from public.scheduler_runs r
  where r.trigger_source <> 'catch_up'
  order by r.started_at desc
  limit 1
$$;
revoke all on function public.scheduler_status() from public, anon;
grant execute on function public.scheduler_status() to authenticated;

-- -----------------------------------------------------------------------------
-- Walrus Memory: new memory kinds for planning, nudges and wellbeing.
-- -----------------------------------------------------------------------------
alter table public.memory_records drop constraint memory_records_kind_check;
alter table public.memory_records add constraint memory_records_kind_check check (
  kind in (
    'recurring_expense', 'budgeting_style', 'overspending_category', 'savings_target',
    'savings_performance', 'goal_progress', 'income_pattern', 'subscription',
    'recommendation', 'recommendation_outcome', 'preference',
    'habit_pattern', 'routine_preference', 'scheduling_preference', 'notification_preference',
    'sleep_pattern', 'activity_routine', 'water_pattern', 'meal_routine', 'mood_pattern',
    'wellbeing_goal', 'review_reflection', 'correction'
  )
);

-- >>> 20261105000100_email_and_theme.sql
-- =============================================================================
-- Stage 6 · Opt-in email notifications and the new default look
-- =============================================================================

-- Email is OFF by default (existing column). Users choose whether to turn it on
-- and what to receive: only summaries and important nudges, or everything that
-- reaches their Nudge Center inbox.
alter table public.notification_preferences
  add column email_mode text not null default 'summaries'
    check (email_mode in ('summaries', 'all'));

grant update (email_enabled, email_mode) on table public.notification_preferences to authenticated;

-- Server-side bookkeeping so every notification is emailed at most once.
-- Users still can only change read_at / dismissed_at (see the column grant).
alter table public.notifications
  add column emailed_at timestamptz,
  add column email_attempts smallint not null default 0 check (email_attempts between 0 and 10);

create index notifications_email_pending_idx
  on public.notifications (user_id, created_at)
  where emailed_at is null and status = 'delivered';

-- AVEN's default look is now the dark theme. "system" was only ever the
-- default (never an explicit choice in the old UI's first run), so it moves too.
alter table public.user_preferences alter column theme set default 'dark';
update public.user_preferences set theme = 'dark' where theme = 'system';

commit;
